verus! {

    /// Given a non‐empty vector `c` of 32‐bit floats representing
    /// the coefficients of the polynomial
    ///    p(x) = c[0] + c[1]·x + … + c[n−1]·xⁿ⁻¹,
    /// return a new vector of length n+1 representing the coefficients
    /// of x·p(x).  Equivalently, the result is
    ///    [0.0, c[0], c[1], …, c[n−1]].
    fn legmulx(c: Vec<f32>) -> (result: Vec<f32>)
        requires
            c.len() > 0,
        ensures
            result.len() == c.len() + 1,
        ensures
            result[0] == 0.0_f32,
        ensures
            forall(|j: usize| j < c.len() ==> result[j + 1] == c[j]),
    {
        // Pre‐allocate space for performance (not strictly necessary for correctness).
        let mut result: Vec<f32> = Vec::with_capacity(c.len() + 1);

        // The constant term of x·p(x) is zero.
        result.push(0.0_f32);

        // We'll build up the rest of the coefficients by shifting.
        let mut i: usize = 0;
        while i < c.len()
            invariant
                // We never exceed the final length.
                i <= c.len(),
            invariant
                // After i steps, result.len() == i + 1.
                result.len() == i + 1,
            invariant
                // And for all j < i, result[j+1] == c[j].
                forall(|j: usize| j < i ==> result[j + 1] == c[j])
        {
            result.push(c[i]);
            i += 1;
        }

        // By the end of the loop, i == c.len(), so
        // result.len() == c.len() + 1, and for all j < c.len(),
        // result[j+1] == c[j], as required.
        result
    }

}